// Fills a repo with demo slots and bookings, and walks each booking through the
// workflow, so the notification history is generated by the real code path.
//
// What the demo shows:
//   - every temple has slots at 07:00 and 10:00 (IST) with 2 pandits each, except
//     Mahakaleshwar at 10:00, which has 1 pandit, so its booked days show as "Full";
//   - Kashi Vishwanath is closed one day (both slots closed), and a Shopify order
//     for that day arrives anyway, so it "needs a slot";
//   - one upcoming booking is cancelled (its seat is freed);
//   - one devotee has a mistyped number, so their WhatsApp message fails (Edit + Resend).

import { createBooking, changeStatus, cancelBooking, createBookingsFromShopifyOrder } from './bookings-service.js';
import { createSlots, updateSlot } from './slots-service.js';
import { STATUSES, istDay } from './workflow.js';
import { buildSeedBookings, PUJAS } from './seed-data.js';

const DAY = 24 * 60 * 60 * 1000;

export async function seed(repo, now = new Date()) {
  const day = (offset) => istDay(new Date(now.getTime() + offset * DAY));
  const longAgo = new Date(now.getTime() - 60 * DAY);
  const temples = [...new Set(PUJAS.map((p) => p.templeName))];
  for (const templeName of temples) {
    const range = { templeName, from: day(-12), to: day(21), durationMinutes: 120 };
    if (templeName.startsWith('Mahakaleshwar')) {
      await createSlots(repo, { ...range, times: ['07:00'], capacity: 2 }, { by: 'Setu Admin', now: longAgo });
      await createSlots(repo, { ...range, times: ['10:00'], capacity: 1 }, { by: 'Setu Admin', now: longAgo });
    } else {
      await createSlots(repo, { ...range, times: ['07:00', '10:00'], capacity: 2 }, { by: 'Setu Admin', now: longAgo });
    }
  }
  const slots = await repo.findSlots({});
  const slotAt = (templeName, date) =>
    slots.find((s) => s.templeName === templeName && new Date(s.startsAt).getTime() === new Date(date).getTime());

  const created = [];
  for (const { input, targetStatus, stepTimes } of buildSeedBookings(now)) {
    const slot = slotAt(input.templeName, input.pujaDate);
    let booking = await createBooking(repo, { ...input, slotId: slot?.id }, { source: 'seed', at: stepTimes.Pending });
    const steps = STATUSES.slice(1, STATUSES.indexOf(targetStatus) + 1);
    for (const to of steps) {
      const result = await changeStatus(repo, booking.bookingId, to, {
        videoUrl: to === 'Video Available' ? `https://example.com/puja-videos/${booking.bookingId}` : undefined,
        at: stepTimes[to],
      });
      booking = result.booking;
    }
    created.push(booking);
  }

  // Cancel the pending booking with the latest puja date (the devotee asked to reschedule).
  const pending = created.filter((b) => b.status === 'Pending').sort((a, b) => new Date(b.pujaDate) - new Date(a.pujaDate));
  if (pending.length) {
    const { booking } = await cancelBooking(repo, pending[0].bookingId, {
      reason: 'Devotee asked to reschedule to next month',
      notifyDevotee: true,
      by: 'Setu Admin',
      at: new Date(now.getTime() - 2 * 60 * 60 * 1000),
    });
    created[created.findIndex((b) => b.bookingId === booking.bookingId)] = booking;
  }

  // Kashi Vishwanath is closed for a festival day in 6 days' time...
  const kashi = PUJAS[0];
  const closedDay = day(6);
  for (const s of slots.filter((x) => x.templeName === kashi.templeName && istDay(x.startsAt) === closedDay)) {
    await updateSlot(repo, s.id, { status: 'closed', note: 'Temple closed to visitors for the Ekadashi festival' }, now);
  }
  // ...but a devotee orders a puja for that day on Shopify. It is paid, so it is
  // accepted, and waits for an admin to place it in a slot.
  const [fromShop] = await createBookingsFromShopifyOrder(
    repo,
    {
      id: 820982911946154500,
      email: 'rekha@example.com',
      line_items: [
        {
          title: kashi.pujaName,
          vendor: kashi.templeName,
          price: String(kashi.amount),
          quantity: 1,
          properties: [
            { name: 'Devotee name', value: 'Rekha Sinha' },
            { name: 'WhatsApp number', value: '+91 98123 45678' },
            { name: 'Gotra', value: 'Kashyap' },
            { name: 'Puja date', value: closedDay },
          ],
        },
      ],
    },
    { now: new Date(now.getTime() - 40 * 60 * 1000) },
  );
  created.push(fromShop);
  return created;
}
